-- Atlas KB seed generated from PureLuxe Atlas KB Excel.
-- NOT a migration — supabase db push ignores this folder.
--
-- Source: PureLuxe Atlas KB — Hotels (Countries, Destinations, Hotels).xlsx
-- Hotels: 2252 (duplicates flagged in sheet skipped)
-- Countries: 218 · Cities: 1049
-- Plus Hotel Details / Room Types / Facilities / Spa / Dining where present.
--
-- Depends on:
--   migrations/016_atlas_kb.sql (+ 021 for style_tags / price_tier)
--   seeds/011_rate_layer.sql (destination profiles)
-- Prefer rate seeds first if you want properties ↔ curated_hotel_id links.
--
-- Safe to re-run: inserts skip existing natural keys.
-- Regenerated by: seeds/_generate/generate_atlas_kb.py

-- =============================================================================
-- 1. Sources
-- =============================================================================

INSERT INTO public.kb_sources (name, source_type, terms_notes, active)
SELECT v.name, 'other', v.notes, true
FROM (VALUES
  ('PureLuxe Atlas KB Excel', 'Master hotel directory from founder Atlas workbook'),
  ('Contracted rate PDF', 'Imported from Atlas Hotels Source column'),
  ('Contracted rate PDF / Excel', 'Imported from Atlas Hotels Source column'),
  ('Contracted rate letter', 'Imported from Atlas Hotels Source column'),
  ('Dorchester Collection — dorchestercollection.com', 'Imported from Atlas Hotels Source column'),
  ('Four Seasons — FourSeasons_Key_Property_Contacts.csv (user-supplied internal property directory, addresses parsed for co', 'Imported from Atlas Hotels Source column'),
  ('IHG Destined Lookbook (user-uploaded partner directory, IHG Luxury & Lifestyle brands)', 'Imported from Atlas Hotels Source column'),
  ('LHW Hotel Contacts CSV (user-uploaded; lhw_hotel_contacts_1.csv) — fills a North America gap the original lhw.com region', 'Imported from Atlas Hotels Source column'),
  ('Leading Hotels of the World — lhw.com/find-a-hotel/browse-by-list', 'Imported from Atlas Hotels Source column'),
  ('Mandarin Oriental Hotel Group — Wikipedia (as of May 2026 per article)', 'Imported from Atlas Hotels Source column'),
  ('Peninsula Hotels — Wikipedia (brand''s own site returned CLIENT_ERROR)', 'Imported from Atlas Hotels Source column'),
  ('PureLuxe Atlas KB — Japan worked example', 'Imported from Atlas Hotels Source column'),
  ('PureLuxe Atlas KB — added by hand', 'Imported from Atlas Hotels Source column'),
  ('Rocco Forte Hotels — roccofortehotels.com', 'Imported from Atlas Hotels Source column'),
  ('Rosewood Elite — Property Contacts page (rosewoodhotels.com/elite)', 'Imported from Atlas Hotels Source column'),
  ('Rosewood Hotels & Resorts — Wikipedia (brand''s own site returned only navigation content)', 'Imported from Atlas Hotels Source column'),
  ('Shangri-La Luxury Circle partner directory (user-uploaded; shangrila_hotels_contacts.csv)', 'Imported from Atlas Hotels Source column'),
  ('Traveller Made', 'Imported from Atlas Hotels Source column'),
  ('Traveller Made — full partner directory (user-uploaded; travellermade_hotels.csv)', 'Imported from Atlas Hotels Source column')
) AS v(name, notes)
WHERE NOT EXISTS (
  SELECT 1 FROM public.kb_sources s WHERE lower(s.name) = lower(v.name)
);

