) AS v(country, city, dest)
JOIN public.kb_countries c ON lower(c.name) = lower(v.country)
LEFT JOIN public.destination_profiles dp
  ON v.dest IS NOT NULL AND lower(dp.canonical_name) = lower(v.dest)
WHERE NOT EXISTS (
  SELECT 1 FROM public.kb_cities x
  WHERE x.country_id = c.id AND lower(x.name) = lower(v.city)
)
ORDER BY c.id, lower(v.city), v.city;

-- =============================================================================
-- 3. Hotel entities
-- =============================================================================

INSERT INTO public.kb_entities (
  entity_type, name, brand, kb_tier, provenance, source_id, source_name,
  region_id, country_id, city_id, destination_profile_id,
  address_line_1, latitude, longitude, website_url,
  contract_status, client_ready, placeholder, not_yet_open,
  external_ids, active
)
SELECT DISTINCT ON (ci.id, lower(v.name))
  'hotel',
  v.name,
  NULLIF(v.brand, ''),
  v.kb_tier,
  'kb',
  src.id,
  v.source_name,
  co.region_id,
  co.id,
  ci.id,
  ci.destination_profile_id,
  NULLIF(v.address_line_1, ''),
  NULLIF(v.lat, '')::double precision,
  NULLIF(v.lng, '')::double precision,
  NULLIF(v.website_url, ''),
  v.contract_status,
  v.client_ready::boolean,
  v.placeholder::boolean,
  v.not_yet_open::boolean,
  jsonb_build_object(
    'atlas_sheet_key', v.atlas_key,
    'atlas_region', v.region
  ),
  true
