) AS v(name, brand, kb_tier, source_name, country, city, region, address_line_1, lat, lng, website_url, contract_status, client_ready, placeholder, not_yet_open, atlas_key)
JOIN public.kb_countries co ON lower(co.name) = lower(v.country)
JOIN public.kb_cities ci ON ci.country_id = co.id AND lower(ci.name) = lower(v.city)
LEFT JOIN public.kb_sources src ON lower(src.name) = lower(v.source_name)
WHERE NOT EXISTS (
  SELECT 1 FROM public.kb_entities e
  WHERE e.entity_type = 'hotel'
    AND e.city_id = ci.id
    AND lower(e.name) = lower(v.name)
    AND e.active = true
)
ORDER BY ci.id, lower(v.name), v.name;

INSERT INTO public.kb_entities (
  entity_type, name, brand, kb_tier, provenance, source_id, source_name,
  region_id, country_id, city_id, destination_profile_id,
  address_line_1, latitude, longitude, website_url,
  contract_status, client_ready, placeholder, not_yet_open,
  external_ids, active
)
SELECT DISTINCT ON (ci.id, lower(v.name))
  'hotel',
  v.name,
  NULLIF(v.brand, ''),
  v.kb_tier,
  'kb',
  src.id,
  v.source_name,
  co.region_id,
  co.id,
  ci.id,
  ci.destination_profile_id,
  NULLIF(v.address_line_1, ''),
  NULLIF(v.lat, '')::double precision,
  NULLIF(v.lng, '')::double precision,
  NULLIF(v.website_url, ''),
  v.contract_status,
  v.client_ready::boolean,
  v.placeholder::boolean,
  v.not_yet_open::boolean,
  jsonb_build_object(
    'atlas_sheet_key', v.atlas_key,
    'atlas_region', v.region
  ),
  true
