JOIN public.kb_countries co ON lower(co.name) = lower(v.country)
JOIN public.kb_cities ci ON ci.country_id = co.id AND lower(ci.name) = lower(v.city)
JOIN public.kb_entities e ON e.entity_type = 'hotel' AND e.city_id = ci.id AND lower(e.name) = lower(v.name) AND e.active = true
WHERE NOT EXISTS (SELECT 1 FROM public.kb_hotel_details d WHERE d.entity_id = e.id);

UPDATE public.kb_hotel_details d
SET
  style_tags = CASE WHEN v.style_tags::text[] <> '{}'::text[] THEN v.style_tags::text[] ELSE d.style_tags END,
  price_tier = COALESCE(NULLIF(v.price_tier, ''), d.price_tier),
  amenities = CASE WHEN v.amenities::text[] <> '{}'::text[] THEN v.amenities::text[] ELSE d.amenities END,
  dining_notes = COALESCE(NULLIF(v.dining_notes, ''), d.dining_notes),
  wellness_notes = COALESCE(NULLIF(v.wellness_notes, ''), d.wellness_notes),
