) AS v(hotel, country, city, room_name, room_size, bed_type, room_view, sort_order)
JOIN public.kb_countries co ON lower(co.name) = lower(v.country)
JOIN public.kb_cities ci ON ci.country_id = co.id AND lower(ci.name) = lower(v.city)
JOIN public.kb_entities e ON e.entity_type = 'hotel' AND e.city_id = ci.id AND lower(e.name) = lower(v.hotel) AND e.active = true
WHERE NOT EXISTS (
  SELECT 1 FROM public.kb_hotel_room_categories r
  WHERE r.entity_id = e.id AND lower(r.name) = lower(v.room_name) AND r.active = true
);

