) AS v(hotel, country, city, room_name, room_size, bed_type, room_view, sort_order)
JOIN public.kb_countries co ON lower(co.name) = lower(v.country)
JOIN public.kb_cities ci ON ci.country_id = co.id AND lower(ci.name) = lower(v.city)
JOIN public.kb_entities e ON e.entity_type = 'hotel' AND e.city_id = ci.id AND lower(e.name) = lower(v.hotel) AND e.active = true
WHERE NOT EXISTS (
  SELECT 1 FROM public.kb_hotel_room_categories r
  WHERE r.entity_id = e.id AND lower(r.name) = lower(v.room_name) AND r.active = true
);

-- =============================================================================
-- 6. Link contracted properties ↔ kb_entities (Trip Builder)
-- =============================================================================

UPDATE public.kb_entities e
SET
  property_id = p.id,
  contract_status = 'contracted',
  client_ready = true,
  updated_at = now()
FROM public.properties p
WHERE lower(p.name) = lower('Waldorf Astoria Maldives Ithaafushi')
  AND e.entity_type = 'hotel'
  AND lower(e.name) = lower('Waldorf Astoria Maldives')
  AND e.active = true;

UPDATE public.properties p
SET
  curated_hotel_id = e.id,
  updated_at = now()
FROM public.kb_entities e
WHERE lower(p.name) = lower('Waldorf Astoria Maldives Ithaafushi')
  AND e.entity_type = 'hotel'
  AND lower(e.name) = lower('Waldorf Astoria Maldives')
  AND e.active = true
  AND (p.curated_hotel_id IS DISTINCT FROM e.id);

UPDATE public.properties p
SET
  kb_country_id = e.country_id,
  kb_city_id = e.city_id,
  updated_at = now()
FROM public.kb_entities e
WHERE lower(p.name) = lower('Waldorf Astoria Maldives Ithaafushi')
  AND e.entity_type = 'hotel'
  AND lower(e.name) = lower('Waldorf Astoria Maldives')
  AND e.active = true;

